def distinct_permutations(values):
    ordered = sorted(values)
    used = [False] * len(ordered)
    result, path = [], []

    def place():
        if len(path) == len(ordered):
            result.append(path[:])
            return
        for i in range(len(ordered)):
            if used[i]:
                continue
            if i > 0 and ordered[i] == ordered[i - 1] and not used[i - 1]:
                continue
            used[i] = True
            path.append(ordered[i])
            place()
            path.pop()
            used[i] = False

    place()
    return result
